#include <iostream>
#include <cstdio>
#include <vector>
#include <array>
#include <set>
#include <map>
using std::cin;
using std::cout;
using std::cerr;
using std::endl;
using std::pair;
using std::make_pair;
using std::vector;
using std::min;
using std::max;
using std::array;
using std::set;
using std::map;

typedef long long int ll;

ll n, q;
vector<ll> a;


const ll maxv = 1'000'009;

ll accum_sum[maxv + 1];
ll accum_cnt[maxv + 1];

void solve () {
	for (ll i = 0; i < n; i++) {
		accum_sum[a[i]] += a[i];
		accum_cnt[a[i]] += 1;
	}
	for (ll i = 1; i <= maxv; i++) {
		accum_sum[i] += accum_sum[i-1];
		accum_cnt[i] += accum_cnt[i-1];
	}
	// accum_sum[i] := a[0] + ... + a[i]
	// accum_cnt[i] := number of x s.t. a[x] <= i 

	for (ll qi = 0; qi < q; qi++) {
		ll b;
		cin >> b;

		ll ans = 1 + accum_sum[b-1] + (n - accum_cnt[b-1]) * (b-1);
		if (accum_cnt[b-1] == n) {
			cout << "-1" << "\n";
		} else {
			cout << ans << "\n";
		}
	}

	return;
}

int main (void) {
	std::ios_base::sync_with_stdio(false);
	cin.tie(nullptr);

	cin >> n >> q;
	a.resize(n);
	for (ll i = 0; i < n; i++) {
		cin >> a[i];
	}

	solve();

	return 0;
}
